//! The speech of the Russian release, which isn't the game's
//! ([docs/formats/russian-release.md](../../../../docs/formats/russian-release.md)).
//!
//! The release's makers recorded the pilots' lines in Russian but had no encoder for the game's
//! speech codec ([`voice.zig`](../voice.zig)). They stored each line in a format of their own
//! inside a speech file, and patched the game's executable to play it: a code section of 4096
//! bytes after the game's, signed "Patch Generated by DDeM 06/05/2000 especially for 7Wolf",
//! with hooks in `speech_unscramble` (`0x00462000`), `speech_timer` (`0x004621EB`, `0x00462236`)
//! and `voice_init` (`0x004A7290`). OpenReliant plays the same files without the patch.
//!
//! A line keeps the game's header (`cbox.Header`). Its stream starts with `tag` and isn't
//! scrambled. Each byte after the tag is one sample at half the speech's rate, 11,025 Hz, which
//! the patch looks up in a table of 256 16-bit samples and writes twice.

const std = @import("std");

/// What a line's stream starts with, where the game's own starts with its codec's header.
pub const tag = "DDeM";

/// How many of the speech's samples each byte makes: the patch writes each twice (four words of
/// the game's stereo).
pub const samples_a_byte = 2;

/// The largest sample the table's curve reaches, at a byte of 127, before it wraps.
const full_scale = 65535;
/// The byte the curve reaches `full_scale` at.
const steps = 127;

/// The sample of each byte, as the patch's table has it (`0x00628110` in the Russian executable).
/// A byte is a signed value, and 0 is silence. From 1 to 127 it makes `full_scale` to the power of
/// the byte over `steps`, rounded, and never less than the byte itself, so that quiet samples keep their steps
/// and loud ones reach far: a companding curve. A negative byte makes the same with its sign
/// turned.
///
/// The curve passes 32767 at a byte of 120, and the table holds 16 bits, so those eight samples
/// either way wrap round to the other sign, as the patch plays them. -128 makes 1, as the table
/// has it.
///
/// **Improvement:** OpenReliant works the table out, where the patch carries it.
pub const table: [256]i16 = made: {
    @setEvalBranchQuota(100_000);
    var samples: [256]i16 = undefined;
    samples[0] = 0;
    for (1..steps + 1) |byte| {
        const curve: u32 = @intFromFloat(@round(std.math.pow(f64, full_scale, @as(f64, @floatFromInt(byte)) / steps)));
        const wrapped: u16 = @truncate(@max(curve, byte));
        samples[byte] = @bitCast(wrapped);
    }
    for (1..steps + 1) |byte| samples[256 - byte] = -samples[byte];
    samples[lowest] = lowest_sample;
    break :made samples;
};

/// The byte of -128, which has no positive twin, and the sample the table gives it.
const lowest = 128;
const lowest_sample = 1;

/// Whether `stream`, a speech file's past its header, is in this format.
pub fn holds(stream: []const u8) bool {
    return std.mem.startsWith(u8, stream, tag);
}

/// Decodes `stream`, which `holds` knows, into `out`, the samples the line's header counts: each
/// byte past the tag twice, and silence where the bytes run out before the samples do.
pub fn decode(out: []i16, stream: []const u8) void {
    const bytes = stream[tag.len..];
    for (out, 0..) |*sample, at| {
        const byte = at / samples_a_byte;
        sample.* = if (byte < bytes.len) table[bytes[byte]] else 0;
    }
}

test table {
    // Quiet samples are the byte itself, either way.
    try std.testing.expectEqual(0, table[0]);
    try std.testing.expectEqual(43, table[43]);
    try std.testing.expectEqual(-1, table[255]);
    try std.testing.expectEqual(-43, table[213]);
    // Past 43 the curve takes over.
    try std.testing.expectEqual(47, table[44]);
    try std.testing.expectEqual(1081, table[80]);
    try std.testing.expectEqual(32589, table[119]);
    try std.testing.expectEqual(-32589, table[137]);
    // From 120 it wraps round, as the patch's table does.
    try std.testing.expectEqual(-29973, table[120]);
    try std.testing.expectEqual(-1, table[127]);
    try std.testing.expectEqual(29973, table[136]);
    try std.testing.expectEqual(1, table[129]);
    try std.testing.expectEqual(1, table[128]);
}

test decode {
    try std.testing.expect(holds("DDeM\x01"));
    try std.testing.expect(!holds("DDe"));
    try std.testing.expect(!holds("\xF1\x38\x10\x04"));
    // Each byte twice, and silence past the last.
    var out: [6]i16 = undefined;
    decode(&out, "DDeM\x02\x50");
    try std.testing.expectEqualSlices(i16, &.{ 2, 2, 1081, 1081, 0, 0 }, &out);
}
